import{_ as a,o as n,c as o,a2 as t}from"./chunks/framework.CWgsre3x.js";const v=JSON.parse('{"title":"Conversational booking and consent","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/conversational-booking.md","filePath":"integrations/conversational-booking.md"}'),i={name:"integrations/conversational-booking.md"};function s(r,e,c,l,d,p){return n(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="conversational-booking-and-consent" tabindex="-1">Conversational booking and consent <a class="header-anchor" href="#conversational-booking-and-consent" aria-label="Permalink to &quot;Conversational booking and consent&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Source-reviewed draft · v0.7.9 reference. Confirm availability and permissions against the approved target release.</p></div><h2 id="sandbox-workflow" tabindex="-1">Sandbox workflow <a class="header-anchor" href="#sandbox-workflow" aria-label="Permalink to &quot;Sandbox workflow&quot;">​</a></h2><p>The source supports WhatsApp, Meta Messenger and Instagram simulations, in English, Greek, Italian, French, German and Spanish. This is not evidence of an active external messaging account.</p><ol><li>In an authorized sandbox, select the channel and language.</li><li>Provide a synthetic booking message, contact information and the actual consent state.</li><li>Review extracted locations, passenger count, service mode and validation issues.</li><li>If the result is ready for handoff, use <strong>Handoff to Booking Form</strong> and verify the prefilled fields before submitting an authorized booking.</li></ol><h2 id="consent-and-escalation" tabindex="-1">Consent and escalation <a class="header-anchor" href="#consent-and-escalation" aria-label="Permalink to &quot;Consent and escalation&quot;">​</a></h2><p><code>pending_consent</code> is the default when consent is absent. <code>opted_in_transactional</code> represents explicit transactional consent; <code>opted_out</code> blocks automated quoting. Escalate uncertain requests for human review. Do not assume marketing consent.</p><p>Passenger email remains optional. A sandbox reply or persisted conversation does not prove external delivery.</p><p>See <a href="/plus/create-reservation.html">Create a reservation</a>.</p><h2 id="changes-described-in-v0-7-14" tabindex="-1">Changes described in v0.7.14 <a class="header-anchor" href="#changes-described-in-v0-7-14" aria-label="Permalink to &quot;Changes described in v0.7.14&quot;">​</a></h2><p>The release describes improvements to conversational reservation handoff. In an authorized test environment, verify extracted details and consent state, review the handoff, and confirm the booking only through the approved workflow. Do not infer live channel activation or message delivery. Passenger email remains optional.</p><p>See <a href="/release-notes/">Release Notes</a>.</p><h2 id="ai-copilot-and-persistent-conversion-—-v0-7-26" tabindex="-1">AI Copilot and persistent conversion — v0.7.26 <a class="header-anchor" href="#ai-copilot-and-persistent-conversion-—-v0-7-26" aria-label="Permalink to &quot;AI Copilot and persistent conversion — v0.7.26&quot;">​</a></h2><p>Review the extracted service, date/time, route, passenger count, capacity, contact and quote context in the approved conversation workspace. Use the human takeover path if information is uncertain or the passenger requests escalation. Do not let AI invent tariffs, contacts or availability. Verify CRM matching and independently confirm ambiguous customers. Use phone-only booking where appropriate without fabricated email.</p><p>The persistent conversion requires AI management and reservation-write authorization and has transactional duplicate/concurrency protection. Review the resulting reservation reference and status before trying again. An AI draft or handoff is not a confirmed booking. Real messaging and external AI acceptance require separate approval. See <a href="/plus/passenger-notifications.html">Notifications</a> and <a href="/integrations/ai-messaging-setup.html">AI and messaging setup</a>.</p>',15)])])}const f=a(i,[["render",s]]);export{v as __pageData,f as default};
